#define _GNU_SOURCE
#include <ctype.h>
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <termios.h>
#include <time.h>
#include <unistd.h>

struct Options {
    int show_seconds;
    int screensaver;
    int box;
    int centered;
    int color;
    int bold;
    int twelve;
    int utc;
    int rebound;
    int noquit;
    int hide_date;
    int blink_colon;
    int delay_s;
    long delay_ns;
    const char *date_fmt;
};

static struct termios saved_termios;
static int have_saved_termios = 0;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t need_cleanup = 0;
static int in_alt_screen = 0;

static const char *help_lines[] = {
"usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty] ",
"    -s            Show seconds",
"    -S            Screensaver mode",
"    -x            Show box",
"    -c            Set the clock at the center of the terminal",
"    -C [0-7]      Set the clock color",
"    -b            Use bold colors",
"    -t            Set the hour in 12h format",
"    -u            Use UTC time",
"    -T tty        Display the clock on the specified terminal",
"    -r            Do rebound the clock",
"    -f format     Set the date format",
"    -n            Don't quit on keypress",
"    -v            Show tty-clock version",
"    -i            Show some info about tty-clock",
"    -h            Show this page",
"    -D            Hide date",
"    -B            Enable blinking colon",
"    -d delay      Set the delay between two redraws of the clock. Default 1s. ",
"    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns."
};

static void usage(void) {
    puts(help_lines[0]);
    for (int i = 1; i <= 17; ++i) printf("%-65s\n", help_lines[i]);
    puts(help_lines[18]);
    puts(help_lines[19]);
}

static void cleanup_terminal(void) {
    if (have_saved_termios) tcsetattr(STDIN_FILENO, TCSANOW, &saved_termios);
    if (in_alt_screen) {
        /* make a best-effort ncurses-like restoration */
        write(STDOUT_FILENO, "\033[?12l\033[?25h\033[?1049l\033[?1l\033>", 33);
        in_alt_screen = 0;
    }
}

static void on_signal(int sig) {
    (void)sig;
    running = 0;
    need_cleanup = 1;
}

static void fatal_tty_error(void) {
    fprintf(stderr, "Error opening terminal: unknown.\n");
    exit(1);
}

static void validate_tty(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) {
        fprintf(stderr, "tty-clock: error: couldn't stat '%s': %s.\n", path, strerror(errno));
        exit(1);
    }
    if (!S_ISCHR(st.st_mode)) {
        fprintf(stderr, "tty-clock: error: '%s' doesn't appear to be a character device.\n", path);
        exit(1);
    }
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "tty-clock: error: couldn't open '%s': %s.\n", path, strerror(errno));
        exit(1);
    }
    dup2(fd, STDIN_FILENO);
    dup2(fd, STDOUT_FILENO);
    if (fd > 1) close(fd);
}

static int term_rows = 24, term_cols = 80;
static int pos_x = 0, pos_y = 0;
static int dx = 1, dy = 1;

static void get_size(void) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0) {
        if (ws.ws_row > 0) term_rows = ws.ws_row;
        if (ws.ws_col > 0) term_cols = ws.ws_col;
    }
}

static int geo_w(const struct Options *o) { return o->show_seconds ? 54 : 35; }
static int geo_h(const struct Options *o) { (void)o; return 7; }

static void clamp_pos(const struct Options *o) {
    int w = geo_w(o), h = geo_h(o);
    int maxx = term_cols - w; if (maxx < 0) maxx = 0;
    int maxy = term_rows - h; if (maxy < 0) maxy = 0;
    if (pos_x < 0) pos_x = 0; if (pos_x > maxx) pos_x = maxx;
    if (pos_y < 0) pos_y = 0; if (pos_y > maxy) pos_y = maxy;
}

static void recenter(const struct Options *o) {
    int w = geo_w(o), h = geo_h(o);
    pos_x = term_cols / 2 - w / 2;
    pos_y = term_rows / 2 - h / 2;
    clamp_pos(o);
}

static void mvcur(int r0, int c0) {
    if (r0 < 0) r0 = 0; if (c0 < 0) c0 = 0;
    printf("\033[%d;%dH", r0 + 1, c0 + 1);
}

static void reset_attr(void) { fputs("\033[0m", stdout); }
static void set_bg(const struct Options *o, int blink) {
    if (o->bold || blink) printf("\033[%d;4%dm", (o->bold || blink) ? 5 : 0, o->color);
    else printf("\033[4%dm", o->color);
}
static void set_fg(const struct Options *o) {
    if (o->bold) printf("\033[1;3%dm", o->color);
    else printf("\033[3%dm", o->color);
}

static void spaces(int n) { while (n-- > 0) putchar(' '); }

static const char *digits[10][5] = {
    {"######", "##  ##", "##  ##", "##  ##", "######"},
    {"    ##", "    ##", "    ##", "    ##", "    ##"},
    {"######", "    ##", "######", "##    ", "######"},
    {"######", "    ##", "######", "    ##", "######"},
    {"##  ##", "##  ##", "######", "    ##", "    ##"},
    {"######", "##    ", "######", "    ##", "######"},
    {"######", "##    ", "######", "##  ##", "######"},
    {"######", "    ##", "    ##", "    ##", "    ##"},
    {"######", "##  ##", "######", "##  ##", "######"},
    {"######", "##  ##", "######", "    ##", "######"}
};

static void draw_digit(int d, int r, int c, const struct Options *o) {
    if (d < 0 || d > 9) return;
    for (int row = 0; row < 5; ++row) {
        int col = 0;
        while (col < 6) {
            if (digits[d][row][col] == '#') {
                int start = col;
                while (col < 6 && digits[d][row][col] == '#') col++;
                mvcur(r + row, c + start);
                set_bg(o, 0);
                spaces(col - start);
                reset_attr();
            } else col++;
        }
    }
}

static void draw_colon(int r, int c, const struct Options *o) {
    int blink = o->blink_colon;
    mvcur(r + 1, c); set_bg(o, blink); spaces(2); reset_attr();
    mvcur(r + 3, c); set_bg(o, blink); spaces(2); reset_attr();
}

static void acs_char(char ch) {
    fputs("\033(0", stdout);
    putchar(ch);
    fputs("\033(B", stdout);
}
static void acs_hline(int n) { fputs("\033(0", stdout); while (n-- > 0) putchar('q'); fputs("\033(B", stdout); }

static void draw_box_rect(int r, int c, int h, int w) {
    if (w < 2 || h < 2) return;
    mvcur(r, c); acs_char('l'); acs_hline(w - 2); acs_char('k');
    for (int y = 1; y < h - 1; ++y) { mvcur(r + y, c); acs_char('x'); mvcur(r + y, c + w - 1); acs_char('x'); }
    mvcur(r + h - 1, c); acs_char('m'); acs_hline(w - 2); acs_char('j');
}

static void make_date(const struct Options *o, const struct tm *tmv, char *buf, size_t sz) {
    char tmp[512];
    const char *fmt = o->date_fmt ? o->date_fmt : "%Y-%m-%d";
    if (strftime(tmp, sizeof(tmp), fmt, tmv) == 0) tmp[0] = '\0';
    if (o->twelve) snprintf(buf, sz, "%s [%s]", tmp, tmv->tm_hour >= 12 ? "PM" : "AM");
    else snprintf(buf, sz, "%s", tmp);
}

static void draw_all(const struct Options *o) {
    get_size();
    if (o->centered) recenter(o); else clamp_pos(o);

    time_t now = time(NULL);
    struct tm tmstore;
    struct tm *tmv = o->utc ? gmtime_r(&now, &tmstore) : localtime_r(&now, &tmstore);
    if (!tmv) return;

    char tbuf[16];
    int hour = tmv->tm_hour;
    if (o->twelve) {
        hour %= 12;
        if (hour == 0) hour = 12;
    }
    if (o->show_seconds) snprintf(tbuf, sizeof(tbuf), "%02d%02d%02d", hour, tmv->tm_min, tmv->tm_sec);
    else snprintf(tbuf, sizeof(tbuf), "%02d%02d", hour, tmv->tm_min);

    char dbuf[512];
    make_date(o, tmv, dbuf, sizeof(dbuf));
    int dlen = (int)strlen(dbuf);

    fputs("\033[H\033[2J", stdout);

    int w = geo_w(o);
    int top = pos_y;
    int left = pos_x;
    if (o->box) draw_box_rect(top, left, 7, w);

    int digit_r = top + 1;
    int digit_c = left + 1;
    draw_digit(tbuf[0] - '0', digit_r, digit_c, o);
    draw_digit(tbuf[1] - '0', digit_r, digit_c + 7, o);
    draw_colon(digit_r, digit_c + 15, o);
    draw_digit(tbuf[2] - '0', digit_r, digit_c + 19, o);
    draw_digit(tbuf[3] - '0', digit_r, digit_c + 26, o);
    if (o->show_seconds) {
        draw_colon(digit_r, digit_c + 34, o);
        draw_digit(tbuf[4] - '0', digit_r, digit_c + 38, o);
        draw_digit(tbuf[5] - '0', digit_r, digit_c + 45, o);
    }

    if (!o->hide_date) {
        int date_text_c = left + w / 2 - dlen / 2;
        if (date_text_c < 0) date_text_c = 0;
        if (o->box) {
            int bw = dlen + 2;
            int bc = left + w / 2 - bw / 2;
            if (bc < 0) bc = 0;
            draw_box_rect(top + 6, bc, 3, bw);
            mvcur(top + 7, bc + 1);
            set_fg(o); fputs(dbuf, stdout); reset_attr();
        } else {
            mvcur(top + 7, date_text_c);
            set_fg(o); fputs(dbuf, stdout); reset_attr();
        }
    }
    fflush(stdout);
}

static void setup_terminal(void) {
    const char *term = getenv("TERM");
    if (!term || strcmp(term, "unknown") == 0) fatal_tty_error();
    if (isatty(STDIN_FILENO) && tcgetattr(STDIN_FILENO, &saved_termios) == 0) {
        have_saved_termios = 1;
        struct termios raw = saved_termios;
        raw.c_lflag &= ~(ICANON | ECHO);
        raw.c_cc[VMIN] = 0;
        raw.c_cc[VTIME] = 0;
        tcsetattr(STDIN_FILENO, TCSANOW, &raw);
    }
    int fl = fcntl(STDIN_FILENO, F_GETFL, 0);
    if (fl >= 0) fcntl(STDIN_FILENO, F_SETFL, fl | O_NONBLOCK);

    fputs("\033[?1049h\033[?25l\033[H\033[2J", stdout);
    fflush(stdout);
    in_alt_screen = 1;
}

static void handle_key(struct Options *o, int ch) {
    if (ch < 0) return;
    if (o->screensaver) {
        if (!o->noquit) running = 0;
        return;
    }
    ch = tolower((unsigned char)ch);
    if (ch == 'q') { if (!o->noquit) running = 0; }
    else if (ch == 's') o->show_seconds = !o->show_seconds;
    else if (ch == 't') o->twelve = !o->twelve;
    else if (ch == 'x') o->box = !o->box;
    else if (ch == 'c') { o->centered = !o->centered; if (o->centered) recenter(o); }
    else if (ch == 'b') o->bold = !o->bold;
    else if (ch == 'r') o->rebound = !o->rebound;
    else if (ch >= '0' && ch <= '7') o->color = ch - '0';
    else if (!o->centered) {
        if (ch == 'h') pos_x--;
        else if (ch == 'l') pos_x++;
        else if (ch == 'k') pos_y--;
        else if (ch == 'j') pos_y++;
        clamp_pos(o);
    }
}

static void read_keys(struct Options *o) {
    char buf[64];
    for (;;) {
        ssize_t n = read(STDIN_FILENO, buf, sizeof(buf));
        if (n > 0) { for (ssize_t i = 0; i < n; ++i) handle_key(o, (unsigned char)buf[i]); }
        else break;
    }
}

static void rebound_step(const struct Options *o) {
    if (!o->rebound || o->centered) return;
    int maxx = term_cols - geo_w(o); if (maxx < 0) maxx = 0;
    int maxy = term_rows - geo_h(o); if (maxy < 0) maxy = 0;
    pos_x += dx; pos_y += dy;
    if (pos_x <= 0) { pos_x = 0; dx = 1; }
