    int blink_colon;
    int delay_s;
    long delay_ns;
    const char *date_fmt;
};

static struct termios saved_termios;
static int have_saved_termios = 0;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t need_cleanup = 0;
static int in_alt_screen = 0;

static const char *help_lines[] = {
"usage : tty-clock [-iuvsScbtrahDBxn] [-C [0-7]] [-f format] [-d delay] [-a nsdelay] [-T tty] ",
"    -s            Show seconds",
"    -S            Screensaver mode",
"    -x            Show box",
"    -c            Set the clock at the center of the terminal",
"    -C [0-7]      Set the clock color",
"    -b            Use bold colors",
"    -t            Set the hour in 12h format",
"    -u            Use UTC time",
"    -T tty        Display the clock on the specified terminal",
"    -r            Do rebound the clock",
"    -f format     Set the date format",
"    -n            Don't quit on keypress",
"    -v            Show tty-clock version",
"    -i            Show some info about tty-clock",
"    -h            Show this page",
"    -D            Hide date",
"    -B            Enable blinking colon",
"    -d delay      Set the delay between two redraws of the clock. Default 1s. ",
"    -a nsdelay    Additional delay between two redraws in nanoseconds. Default 0ns."
};

static void usage(void) {
    puts(help_lines[0]);
    for (int i = 1; i <= 17; ++i) printf("%-65s\n", help_lines[i]);
    puts(help_lines[18]);
    puts(help_lines[19]);
}

static void cleanup_terminal(void) {
    if (have_saved_termios) tcsetattr(STDIN_FILENO, TCSANOW, &saved_termios);
    if (in_alt_screen) {
        /* make a best-effort ncurses-like restoration */
        write(STDOUT_FILENO, "\033[?12l\033[?25h\033[?1049l\033[?1l\033>", 33);
        in_alt_screen = 0;
    }
}

static void on_signal(int sig) {
    (void)sig;
    running = 0;
    need_cleanup = 1;
}

static void fatal_tty_error(void) {
    fprintf(stderr, "Error opening terminal: unknown.\n");
    exit(1);
}

static void validate_tty(const char *path) {
    struct stat st;
    if (stat(path, &st) != 0) {
        fprintf(stderr, "tty-clock: error: couldn't stat '%s': %s.\n", path, strerror(errno));
        exit(1);
    }
    if (!S_ISCHR(st.st_mode)) {
        fprintf(stderr, "tty-clock: error: '%s' doesn't appear to be a character device.\n", path);
        exit(1);
    }
    int fd = open(path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "tty-clock: error: couldn't open '%s': %s.\n", path, strerror(errno));
        exit(1);
    }
    dup2(fd, STDIN_FILENO);
    dup2(fd, STDOUT_FILENO);
    if (fd > 1) close(fd);
}

static int term_rows = 24, term_cols = 80;
static int pos_x = 0, pos_y = 0;
static int dx = 1, dy = 1;

static void get_size(void) {
    struct winsize ws;
    if (ioctl(STDOUT_FILENO, TIOCGWINSZ, &ws) == 0) {
        if (ws.ws_row > 0) term_rows = ws.ws_row;
        if (ws.ws_col > 0) term_cols = ws.ws_col;
    }
}

static int geo_w(const struct Options *o) { return o->show_seconds ? 54 : 35; }
static int geo_h(const struct Options *o) { (void)o; return 7; }

static void clamp_pos(const struct Options *o) {
    int w = geo_w(o), h = geo_h(o);
    int maxx = term_cols - w; if (maxx < 0) maxx = 0;
    int maxy = term_rows - h; if (maxy < 0) maxy = 0;
    if (pos_x < 0) pos_x = 0; if (pos_x > maxx) pos_x = maxx;
    if (pos_y < 0) pos_y = 0; if (pos_y > maxy) pos_y = maxy;
}

static void recenter(const struct Options *o) {
    int w = geo_w(o), h = geo_h(o);
    pos_x = term_cols / 2 - w / 2;
    pos_y = term_rows / 2 - h / 2;
    clamp_pos(o);
}

static void mvcur(int r0, int c0) {
    if (r0 < 0) r0 = 0; if (c0 < 0) c0 = 0;
