static void reset_attr(void) { fputs("\033[0m", stdout); }
static void set_bg(const struct Options *o, int blink) {
    if (o->bold || blink) printf("\033[%d;4%dm", (o->bold || blink) ? 5 : 0, o->color);
    else printf("\033[4%dm", o->color);
}
static void set_fg(const struct Options *o) {
    if (o->bold) printf("\033[1;3%dm", o->color);
    else printf("\033[3%dm", o->color);
}

static void spaces(int n) { while (n-- > 0) putchar(' '); }

static const char *digits[10][5] = {
    {"######", "##  ##", "##  ##", "##  ##", "######"},
    {"    ##", "    ##", "    ##", "    ##", "    ##"},
    {"######", "    ##", "######", "##    ", "######"},
    {"######", "    ##", "######", "    ##", "######"},
    {"##  ##", "##  ##", "######", "    ##", "    ##"},
    {"######", "##    ", "######", "    ##", "######"},
    {"######", "##    ", "######", "##  ##", "######"},
    {"######", "    ##", "    ##", "    ##", "    ##"},
    {"######", "##  ##", "######", "##  ##", "######"},
    {"######", "##  ##", "######", "    ##", "######"}
};

static void draw_digit(int d, int r, int c, const struct Options *o) {
    if (d < 0 || d > 9) return;
    for (int row = 0; row < 5; ++row) {
        int col = 0;
        while (col < 6) {
            if (digits[d][row][col] == '#') {
                int start = col;
                while (col < 6 && digits[d][row][col] == '#') col++;
                mvcur(r + row, c + start);
                set_bg(o, 0);
                spaces(col - start);
