static void handle_key(struct Options *o, int ch) {
    if (ch < 0) return;
    if (o->screensaver) {
        if (!o->noquit) running = 0;
        return;
    }
    ch = tolower((unsigned char)ch);
    if (ch == 'q') { if (!o->noquit) running = 0; }
    else if (ch == 's') o->show_seconds = !o->show_seconds;
    else if (ch == 't') o->twelve = !o->twelve;
